{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T011142Z/cell-p8y6kT/src/policies.js","content":"/**
 * The two policy kinds a limiter file can declare. Each policy keeps one
 * independent state per key, created the first time that key reaches it.
 */

/**
 * A token bucket. Tokens are tracked as an integer numerator over the fixed
 * denominator `per`, so refilling by a partial period never loses precision:
 * after `n` ticks the numerator gains exactly `refill * n`.
 */
export class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = BigInt(capacity)
    this.refill = BigInt(refill)
    this.per = BigInt(per)
    this.fullNumerator = this.capacity * this.per
    this.states = new Map()
  }

  #stateFor(key, tick) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { numerator: this.fullNumerator, lastTick: tick }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.#stateFor(key, tick)
    const elapsed = tick - state.lastTick
    if (elapsed > 0n) {
      const gained = this.refill * elapsed
      let numerator = state.numerator + gained
      if (numerator > this.fullNumerator) numerator = this.fullNumerator
      state.numerator = numerator
      state.lastTick = tick
    }
  }

  allow(key) {
    const state = this.states.get(key)
    return state.numerator >= this.per
  }

  record(key) {
    const state = this.states.get(key)
    state.numerator -= this.per
  }
}

/**
 * A sliding window. It remembers the ticks of the requests it recorded for a
 * key, in increasing order, and forgets ticks that have fallen out of the
 * span when it advances.
 */
export class SlidingWindow {
  constructor(limit, span) {
    this.limit = BigInt(limit)
    this.span = BigInt(span)
    this.states = new Map()
  }

  #stateFor(key) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { ticks: [], start: 0 }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.#stateFor(key)
    const threshold = tick - this.span
    while (state.start < state.ticks.length && state.ticks[state.start] <= threshold) {
      state.start += 1
    }
    if (state.start > 1024 && state.start * 2 > state.ticks.length) {
      state.ticks = state.ticks.slice(state.start)
      state.start = 0
    }
  }

  allow(key) {
    const state = this.states.get(key)
    return BigInt(state.ticks.length - state.start) < this.limit
  }

  record(key, tick) {
    const state = this.states.get(key)
    state.ticks.push(tick)
  }
}
"}

