{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T011142Z/cell-p8y6kT/src/parser.js","content":"/**
 * Parses a limiter file into declared policies, routes and events, applying
 * every validation rule from the specification in the order the fields
 * appear on the line.
 */
import { LimiterError } from './errors.js'
import { TokenBucket, SlidingWindow } from './policies.js'

const TOKEN_RE = /^[A-Za-z0-9_.\/:-]+$/
const INT_RE = /^(0|[1-9][0-9]*)$/

function splitLines(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function parseIntField(raw, field, least, line) {
  if (!INT_RE.test(raw) || BigInt(raw) < BigInt(least)) {
    throw new LimiterError(line, `${field} must be an integer of at least ${least}`)
  }
  return BigInt(raw)
}

/**
 * Parses the whole limiter file. Returns `{ policies, routes, events }` on
 * success, where `policies` maps name to a `TokenBucket` or `SlidingWindow`,
 * `routes` is an array of `{ prefix, policyNames }` ordered as declared, and
 * `events` is an array of `{ line, tick, key }` in file order.
 */
export function parseLimiterFile(input) {
  const lines = splitLines(input)
  const policies = new Map()
  const routes = []
  const routePrefixes = new Set()
  const events = []
  let sawEvent = false
  let lastTick = null

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const word = tokens[0]

    if (word === 'bucket') {
      if (sawEvent) throw new LimiterError(lineNumber, 'declarations must come before the first event')
      if (tokens.length !== 5) throw new LimiterError(lineNumber, 'expected bucket <name> <capacity> <refill> <per>')
      const [, name, capacityRaw, refillRaw, perRaw] = tokens
      if (!TOKEN_RE.test(name)) throw new LimiterError(lineNumber, `invalid policy name ${name}`)
      const capacity = parseIntField(capacityRaw, 'capacity', 1, lineNumber)
      const refill = parseIntField(refillRaw, 'refill', 0, lineNumber)
      const per = parseIntField(perRaw, 'per', 1, lineNumber)
      if (policies.has(name)) throw new LimiterError(lineNumber, `policy ${name} is declared twice`)
      policies.set(name, new TokenBucket(capacity, refill, per))
      continue
    }

    if (word === 'window') {
      if (sawEvent) throw new LimiterError(lineNumber, 'declarations must come before the first event')
      if (tokens.length !== 4) throw new LimiterError(lineNumber, 'expected window <name> <limit> <span>')
      const [, name, limitRaw, spanRaw] = tokens
      if (!TOKEN_RE.test(name)) throw new LimiterError(lineNumber, `invalid policy name ${name}`)
      const limit = parseIntField(limitRaw, 'limit', 0, lineNumber)
      const span = parseIntField(spanRaw, 'span', 1, lineNumber)
      if (policies.has(name)) throw new LimiterError(lineNumber, `policy ${name} is declared twice`)
      policies.set(name, new SlidingWindow(limit, span))
      continue
    }

    if (word === 'route') {
      if (sawEvent) throw new LimiterError(lineNumber, 'declarations must come before the first event')
      if (tokens.length < 3) throw new LimiterError(lineNumber, 'expected route <prefix> <policy>...')
      const prefix = tokens[1]
      const policyNames = tokens.slice(2)
      if (!TOKEN_RE.test(prefix)) throw new LimiterError(lineNumber, `invalid route prefix ${prefix}`)
      for (const policyName of policyNames) {
        if (!policies.has(policyName)) throw new LimiterError(lineNumber, `unknown policy ${policyName}`)
      }
      if (routePrefixes.has(prefix)) throw new LimiterError(lineNumber, `prefix ${prefix} is routed twice`)
      routePrefixes.add(prefix)
      routes.push({ prefix, policyNames })
      continue
    }

    if (word === 'event') {
      if (tokens.length !== 3) throw new LimiterError(lineNumber, 'expected event <tick> <key>')
      const [, tickRaw, key] = tokens
      const tick = parseIntField(tickRaw, 'tick', 0, lineNumber)
      if (!TOKEN_RE.test(key)) throw new LimiterError(lineNumber, `invalid key ${key}`)
      if (lastTick !== null && tick < lastTick) {
        throw new LimiterError(lineNumber, `tick ${tick} is before tick ${lastTick}`)
      }
      lastTick = tick
      sawEvent = true
      events.push({ line: lineNumber, tick, key })
      continue
    }

    throw new LimiterError(lineNumber, `unknown directive ${word}`)
  }

  routes.sort((a, b) => b.prefix.length - a.prefix.length)
  return { policies, routes, events }
}
"}

