 * Replays parsed events through the routed policies, producing one verdict
 * per event in log order.
 */

function findRoute(routes, key) {
  for (const route of routes) {
    if (key.startsWith(route.prefix)) return route
  }
  return null
}

/**
 * Runs `events` through `policies`/`routes`. Returns an array of
 * `{ tick, key, allowed, deniedBy }` in event order, where `deniedBy` is the
 * name of the first refusing policy, or `null` when the event was allowed.
 */
export function simulate(policies, routes, events) {
  const results = []
  for (const event of events) {
    const { tick, key } = event
    const route = findRoute(routes, key)
    if (route === null) {
      results.push({ tick, key, allowed: true, deniedBy: null })
      continue
    }

    const routePolicies = route.policyNames.map((name) => policies.get(name))
    for (const policy of routePolicies) policy.advance(key, tick)

    let deniedBy = null
    for (let i = 0; i < routePolicies.length; i++) {
      if (!routePolicies[i].allow(key)) {
        deniedBy = route.policyNames[i]
        break
      }
    }

    if (deniedBy === null) {
      for (const policy of routePolicies) policy.record(key, tick)
    }
    results.push({ tick, key, allowed: deniedBy === null, deniedBy })
  }
  return results
}
"}

