/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */
import { parseLimiterFile } from './parser.js'
import { simulate } from './engine.js'
import { LimiterError } from './errors.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buffer = Buffer.alloc(65536)
  const fs = require('node:fs')
  while (true) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buffer, 0, buffer.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buffer.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function formatReplay(results) {
  const lines = []
  for (const result of results) {
    if (result.allowed) {
      lines.push(`${result.tick} ${result.key} allow`)
    } else {
      lines.push(`${result.tick} ${result.key} deny ${result.deniedBy}`)
    }
  }
  return lines.join('')
}

function formatSummary(results) {
  const perKey = new Map()
  let totalAllowed = 0
  let totalDenied = 0
  for (const result of results) {
    let counts = perKey.get(result.key)
    if (counts === undefined) {
      counts = { allowed: 0, denied: 0 }
      perKey.set(result.key, counts)
    }
    if (result.allowed) {
      counts.allowed += 1
      totalAllowed += 1
    } else {
      counts.denied += 1
      totalDenied += 1
    }
  }
  const keys = [...perKey.keys()].sort()
  const lines = []
  for (const key of keys) {
    const counts = perKey.get(key)
    lines.push(`${key} allowed=${counts.allowed} denied=${counts.denied}\n`)
  }
  lines.push(`total allowed=${totalAllowed} denied=${totalDenied}\n`)
  return lines.join('')
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'replay' && mode !== 'summary')) {
    process.stderr.write('error: usage: cli.js replay|summary\n')
    process.exit(2)
  }

  const input = readStdin()

  let parsed
  try {
    parsed = parseLimiterFile(input)
  } catch (err) {
    if (err instanceof LimiterError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(2)
    }
    throw err
  }

  const results = simulate(parsed.policies, parsed.routes, parsed.events)
  const output = mode === 'replay' ? formatReplay(results) : formatSummary(results)
  process.stdout.write(output)
  process.exit(0)
}

main()
"}

